using Alice.Activities;using Alice.Interaction;
namespace Alice.Perception;
public enum PickupActionOutcome{Committed,Rejected} public enum PickupActionPerceivedFailure{InteractionUnavailable,InteractionChanged,OutOfRange,MethodUnavailable,CapacityUnavailable,SourceUnavailable,AttemptFailed}
public sealed class PickupActionOutcomeReceipt:IEquatable<PickupActionOutcomeReceipt>{public PickupActionOutcomeReceipt(GameActionSpec action,GameActionId id,PickupActionOutcome outcome,PickupActionPerceivedFailure? failure,SimTime time){ArgumentNullException.ThrowIfNull(action);ArgumentNullException.ThrowIfNull(id);if(!Enum.IsDefined(outcome)||failure is not null&&!Enum.IsDefined(failure.Value)||outcome==PickupActionOutcome.Committed&&failure is not null||outcome==PickupActionOutcome.Rejected&&failure is null)throw new ArgumentException();AttemptedAction=action;GameActionId=id;Outcome=outcome;PerceivedFailure=failure;ObservedAt=time;}public GameActionSpec AttemptedAction{get;}public GameActionId GameActionId{get;}public PickupActionOutcome Outcome{get;}public PickupActionPerceivedFailure? PerceivedFailure{get;}public SimTime ObservedAt{get;}public bool Equals(PickupActionOutcomeReceipt? o)=>o is not null&&AttemptedAction==o.AttemptedAction&&GameActionId==o.GameActionId&&Outcome==o.Outcome&&PerceivedFailure==o.PerceivedFailure&&ObservedAt==o.ObservedAt;public override bool Equals(object? o)=>Equals(o as PickupActionOutcomeReceipt);public override int GetHashCode()=>HashCode.Combine(AttemptedAction,GameActionId,Outcome,PerceivedFailure,ObservedAt);}
